/**
 * The subscription is the authority for the plan. Workspaces with no
 * subscription row keep the plan stored on the organization itself, including
 * rows whose two copies already disagree.
 */
function subscriptionPlansFor(orgIds: readonly string[]): Map<string, PlanId> {
  if (orgIds.length === 0) return new Map();
  const rows = getDb()
    .select({ orgId: subscriptions.orgId, plan: subscriptions.plan })
    .from(subscriptions)
    .where(inArray(subscriptions.orgId, [...orgIds]))
    .all();
  return new Map(rows.map((row) => [row.orgId, row.plan]));
}

function withSubscriptionPlan(org: Organization): Organization {
  return withSubscriptionPlans([org])[0] ?? org;
}

function withSubscriptionPlans(
  orgs: readonly Organization[],
): Organization[] {
  const plans = subscriptionPlansFor(orgs.map((org) => org.id));
  return orgs.map((org) => {
    const plan = plans.get(org.id);
    if (!plan || plan === org.plan) return org;
    return { ...org, plan };
  });
}

